class SpellChecker {
    public void check(String text) {
        System.out.println("[SpellChecker] Verifying spelling for: \"" + text + "\"");
    }
}

class WordCounter {
    public int countWords(String text) {
        return text.split("\\s+").length;
    }
}

// TextEditor delegates to two specialized helper objects without multiple inheritance
class TextEditor {
    private SpellChecker spellChecker = new SpellChecker();
    private WordCounter wordCounter = new WordCounter();

    public void analyzeDocument(String text) {
        System.out.println("Analyzing document...");
        spellChecker.check(text); // Delegated call 1
        int count = wordCounter.countWords(text); // Delegated call 2
        System.out.println("Word count: " + count);
    }
}

public class DelegationDemo {
    public static void main(String[] args) {
        TextEditor editor = new TextEditor();
        editor.analyzeDocument("Polymorphism and Composition in Java");
    }
}

