interface CompressionAlgorithm {
    void compress(String filename);
}

class ZipCompression implements CompressionAlgorithm {
    public void compress(String filename) {
        System.out.println("[ZIP] Compressing " + filename + " using Deflate algorithm.");
    }
}

class GzipCompression implements CompressionAlgorithm {
    public void compress(String filename) {
        System.out.println("[GZIP] Compressing " + filename + " using LZ77 algorithm.");
    }
}

class Archiver {
    private CompressionAlgorithm compressor; // Delegate interface

    public Archiver(CompressionAlgorithm compressor) {
        this.compressor = compressor;
    }

    public void setAlgorithm(CompressionAlgorithm newAlgorithm) {
        this.compressor = newAlgorithm;
    }

    // Forwarding method
    public void archive(String filename) {
        compressor.compress(filename);
    }
}

public class StrategyDelegationDemo {
    public static void main(String[] args) {
        Archiver archiver = new Archiver(new ZipCompression());
        archiver.archive("dataset.csv");

        // Swapping the delegate dynamically at runtime
        archiver.setAlgorithm(new GzipCompression());
        archiver.archive("server_logs.txt");
    }
}

