import java.util.Arrays;

interface SortStrategy {
    void sort(int[] arr);
}

class BubbleSort implements SortStrategy {
    @Override
    public void sort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
        System.out.println("[BubbleSort] Completed in O(N^2)");
    }
}

class QuickSort implements SortStrategy {
    @Override
    public void sort(int[] arr) {
        Arrays.sort(arr);
        System.out.println("[QuickSort] Completed in O(N log N)");
    }
}

class DatasetManager {
    private SortStrategy strategy;
    public DatasetManager(SortStrategy strategy) {
        this.strategy = strategy;
    }
    public void setStrategy(SortStrategy strategy) {
        this.strategy = strategy;
    }
    public void sortDataset(int[] arr) {
        strategy.sort(arr);
    }
}

public class SortApp {
    public static void main(String[] args) {
        int[] d1 = {5, 2, 8, 1};
        DatasetManager dm = new DatasetManager(new BubbleSort());
        dm.sortDataset(d1);

        int[] d2 = {9, 3, 7};
        dm.setStrategy(new QuickSort());
        dm.sortDataset(d2);
    }
}

interface DatabaseReader {
    String readSecret(String userRole);
}

class RealDatabaseReader implements DatabaseReader {
    @Override
    public String readSecret(String userRole) {
        return "[SECRET_DATA: 42-ALPHA-OMEGA]";
    }
}

class SecurityProxyReader implements DatabaseReader {
    private DatabaseReader realReader = new RealDatabaseReader();

    @Override
    public String readSecret(String userRole) {
        if ("ADMIN".equalsIgnoreCase(userRole)) {
            return realReader.readSecret(userRole);
        }
        return "[ACCESS DENIED: Insufficient permissions for role " + userRole + "]";
    }
}

public class ProxyApp {
    public static void main(String[] args) {
        DatabaseReader reader = new SecurityProxyReader();
        System.out.println(reader.readSecret("GUEST"));
        System.out.println(reader.readSecret("ADMIN"));
    }
}

