class LightingController {
    public void setLights(String scene) {
        System.out.println("[Lights] Setting scene to: " + scene);
    }
}

class HvacController {
    public void setTemperature(double tempC) {
        System.out.println("[HVAC] Target temp set to: " + tempC + "C");
    }
}

class SecurityController {
    public void setArmed(boolean armed) {
        System.out.println("[Security] System armed: " + armed);
    }
}

class SmartHomeHub {
    private LightingController lighting = new LightingController();
    private HvacController hvac = new HvacController();
    private SecurityController security = new SecurityController();

    public void activateNightMode() {
        System.out.println("=== Activating Night Mode ===");
        lighting.setLights("Dim warm");
        hvac.setTemperature(19.5);
        security.setArmed(true);
    }

    public void activateAwayMode() {
        System.out.println("=== Activating Away Mode ===");
        lighting.setLights("Off");
        hvac.setTemperature(16.0);
        security.setArmed(true);
    }
}

public class HubApp {
    public static void main(String[] args) {
        SmartHomeHub hub = new SmartHomeHub();
        hub.activateNightMode();
        hub.activateAwayMode();
    }
}
